-- Colis 20 : supervision régionale du pointage, sans créer de pointages fictifs.
ALTER TABLE organizations ADD COLUMN commune TEXT;
ALTER TABLE organizations ADD COLUMN contact_phone TEXT;
CREATE TABLE attendance_profile_photos (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 account_id BIGINT NOT NULL REFERENCES accounts(id),mime_type TEXT NOT NULL CHECK(mime_type IN ('image/jpeg','image/png')),
 content BYTEA NOT NULL CHECK(octet_length(content) BETWEEN 16 AND 1048576),
 uploaded_by BIGINT NOT NULL REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX attendance_photos_latest ON attendance_profile_photos(account_id,id DESC);
CREATE TRIGGER attendance_photos_immutable BEFORE UPDATE OR DELETE ON attendance_profile_photos FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
CREATE TABLE attendance_regional_settings (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,region_id BIGINT NOT NULL REFERENCES organizations(id),
 effective_from DATE NOT NULL,agent_alert_min SMALLINT NOT NULL CHECK(agent_alert_min BETWEEN 1 AND 120),
 report_frequency TEXT NOT NULL CHECK(report_frequency IN ('daily','weekly','monthly')),
 author_id BIGINT NOT NULL REFERENCES accounts(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX attendance_regional_settings_lookup ON attendance_regional_settings(region_id,effective_from DESC,id DESC);
CREATE TRIGGER attendance_regional_settings_immutable BEFORE UPDATE OR DELETE ON attendance_regional_settings FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
CREATE TABLE attendance_regional_alerts (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,record_id BIGINT NOT NULL UNIQUE REFERENCES attendance_records(id),
 region_id BIGINT NOT NULL REFERENCES organizations(id),organization_id BIGINT NOT NULL REFERENCES organizations(id),
 severity TEXT NOT NULL CHECK(severity IN ('light','serious','grave','very_grave','on_time')),
 delay_minutes SMALLINT NOT NULL,record_revision INTEGER NOT NULL,
 status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','treated','transmitted','resolved')),
 comment TEXT,transmitted_to BIGINT REFERENCES accounts(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX attendance_regional_alerts_scope ON attendance_regional_alerts(region_id,created_at DESC);
CREATE TRIGGER attendance_regional_alerts_identity_guard BEFORE UPDATE OF record_id,region_id,organization_id,created_at OR DELETE ON attendance_regional_alerts FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
-- Reprendre seulement les retards REELLEMENT enregistrés au colis 19 (sans générer une nouvelle notification).
INSERT INTO attendance_regional_alerts(record_id,region_id,organization_id,severity,delay_minutes,record_revision,created_at,updated_at) SELECT id,region_id,organization_id,severity,delay_minutes,revision,recorded_at,updated_at FROM attendance_records WHERE delay_minutes>0 AND region_id IS NOT NULL;

CREATE TABLE attendance_regional_alert_events (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,alert_id BIGINT NOT NULL REFERENCES attendance_regional_alerts(id),
 actor_id BIGINT REFERENCES accounts(id),action TEXT NOT NULL,old_value JSONB,new_value JSONB NOT NULL,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER attendance_regional_alert_events_immutable BEFORE UPDATE OR DELETE ON attendance_regional_alert_events FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
INSERT INTO attendance_regional_alert_events(alert_id,actor_id,action,new_value,created_at) SELECT al.id,rec.recorded_by,'migration_from_real_record',jsonb_build_object('severity',al.severity,'delay_minutes',al.delay_minutes,'record_revision',al.record_revision,'status',al.status),now() FROM attendance_regional_alerts al JOIN attendance_records rec ON rec.id=al.record_id;

CREATE TABLE attendance_regional_notices (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,region_id BIGINT NOT NULL REFERENCES organizations(id),
 organization_id BIGINT NOT NULL REFERENCES organizations(id),recipient_id BIGINT NOT NULL REFERENCES accounts(id),
 record_id BIGINT REFERENCES attendance_records(id),kind TEXT NOT NULL CHECK(kind IN ('message','explanation','more_info','presentation','establishment')),
 subject TEXT NOT NULL,body TEXT NOT NULL,reason TEXT NOT NULL,observations TEXT,
 present_at TIMESTAMPTZ,present_place TEXT,created_by BIGINT NOT NULL REFERENCES accounts(id),
 notify_head_id BIGINT REFERENCES accounts(id),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','processed','closed')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ,delivered_at TIMESTAMPTZ,read_at TIMESTAMPTZ,
 acknowledged_at TIMESTAMPTZ,replied_at TIMESTAMPTZ,processed_at TIMESTAMPTZ,closed_at TIMESTAMPTZ,
 revision INTEGER NOT NULL DEFAULT 1,CHECK((present_at IS NULL AND present_place IS NULL) OR (present_at IS NOT NULL AND present_place IS NOT NULL))
);
CREATE OR REPLACE FUNCTION guard_attendance_notice_update() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Dossier régional non supprimable'; END IF;
 IF NEW.region_id IS DISTINCT FROM OLD.region_id OR NEW.organization_id IS DISTINCT FROM OLD.organization_id OR NEW.recipient_id IS DISTINCT FROM OLD.recipient_id OR NEW.record_id IS DISTINCT FROM OLD.record_id OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.created_by IS DISTINCT FROM OLD.created_by OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN RAISE EXCEPTION 'Identité du dossier régional non modifiable'; END IF;
 IF OLD.status<>'draft' AND (NEW.subject IS DISTINCT FROM OLD.subject OR NEW.body IS DISTINCT FROM OLD.body OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.observations IS DISTINCT FROM OLD.observations OR NEW.present_at IS DISTINCT FROM OLD.present_at OR NEW.present_place IS DISTINCT FROM OLD.present_place) THEN RAISE EXCEPTION 'Contenu envoyé non modifiable'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER attendance_notices_guard BEFORE UPDATE OR DELETE ON attendance_regional_notices FOR EACH ROW EXECUTE FUNCTION guard_attendance_notice_update();
CREATE INDEX attendance_notices_region ON attendance_regional_notices(region_id,id DESC);
CREATE INDEX attendance_notices_recipient ON attendance_regional_notices(recipient_id,id DESC);
CREATE TABLE attendance_notice_events (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notice_id BIGINT NOT NULL REFERENCES attendance_regional_notices(id),
 actor_id BIGINT NOT NULL REFERENCES accounts(id),action TEXT NOT NULL,note TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER attendance_notice_events_immutable BEFORE UPDATE OR DELETE ON attendance_notice_events FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
CREATE TABLE attendance_notice_files (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,notice_id BIGINT NOT NULL REFERENCES attendance_regional_notices(id),
 uploaded_by BIGINT NOT NULL REFERENCES accounts(id),phase TEXT NOT NULL CHECK(phase IN ('draft','reply')),
 file_name TEXT NOT NULL,mime_type TEXT NOT NULL CHECK(mime_type IN ('application/pdf','image/jpeg','image/png')),
 content BYTEA NOT NULL CHECK(octet_length(content) BETWEEN 8 AND 2097152),created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TRIGGER attendance_notice_files_immutable BEFORE UPDATE OR DELETE ON attendance_notice_files FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
CREATE TABLE attendance_notice_access (
 notice_id BIGINT NOT NULL REFERENCES attendance_regional_notices(id),account_id BIGINT NOT NULL REFERENCES accounts(id),
 granted_by BIGINT NOT NULL REFERENCES accounts(id),role_at_grant TEXT NOT NULL,organization_at_grant BIGINT REFERENCES organizations(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(notice_id,account_id)
);
CREATE TRIGGER attendance_notice_access_immutable BEFORE UPDATE OR DELETE ON attendance_notice_access FOR EACH ROW EXECUTE FUNCTION reject_work_event_mutation();
ALTER TABLE activity_notifications DROP CONSTRAINT activity_notifications_entity_type_check;
ALTER TABLE activity_notifications ADD CONSTRAINT activity_notifications_entity_type_check CHECK(entity_type IN ('message','report','library','calendar','group','correspondence','reminder_instruction','reminder_task','reminder_calendar','training','announcement','teacher_request','academic_term','supervision','supervision_request','timetable','pedagogical_share','grade_assessment','attendance','attendance_notice','attendance_regional_alert'));
